<script setup>defineProps({variant:{type:String,default:'primary'},size:{type:String,default:'md'},type:{type:String,default:'button'},disabled:Boolean,loading:Boolean,block:Boolean});defineEmits(['click'])</script><template><button :type="type" class="btn" :class="[variant,size,{block}]" :disabled="disabled||loading" @click="$emit('click',$event)"><slot/></button></template><style scoped>.btn{border:1px solid var(--line);border-radius:var(--radius-md);padding:8px 13px;font-weight:600;font-size:12px}.sm{padding:5px 9px}.lg{padding:11px 16px}.primary{background:var(--primary);color:var(--on-primary);border-color:var(--primary)}.secondary{background:var(--surface);color:var(--text)}.ghost{background:transparent;color:var(--text)}.danger{background:var(--danger);color:white}.block{width:100%}.btn:disabled{opacity:.55}</style>